/**
 * WordPress dependencies
 */
import { PanelBody } from '@safe-wordpress/components';
import { _x, sprintf } from '@safe-wordpress/i18n';

/**
 * Internal dependencies
 */
import { useExperimentAttribute } from '@nab/data';
import type { ConversionAction, Maybe } from '@nab/types';

/**
 * Internal dependencies
 */
import './style.scss';

import type { Attributes as ElementViewAttributes } from '../../../../../../../../packages/conversion-action-library/element-view/types';
import { createInterpolateElement } from '@wordpress/element';

// NOTE. Right now we assume we can only have *one* action type and *one* visibility action.
export const PageViewTriggers = (): JSX.Element | null => {
	const trigger = useVisibilityTrigger();
	return (
		<PanelBody
			className="nab-experiment-page-view-triggers"
			title={ _x( 'Page View Trigger', 'text', 'nelio-ab-testing' ) }
		>
			<p>{ getLabel( trigger ) }</p>
		</PanelBody>
	);
};

function getLabel(
	trigger: Maybe< ConversionAction< ElementViewAttributes > >
): string | JSX.Element {
	if ( ! trigger ) {
		return _x(
			'Counts the page view on page visit.',
			'text',
			'nelio-ab-testing'
		);
	}

	switch ( trigger.attributes.mode ) {
		case 'css':
			return formatHtml(
				sprintf(
					/* translators: %s: CSS selector, such as "a.button". */
					_x(
						'Counts the page view when a visitor views an element matching the CSS selector %s on a tested page.',
						'text',
						'nelio-ab-testing'
					),
					`<code>${ trigger.attributes.value }</code>`
				)
			);

		case 'id':
			return formatHtml(
				sprintf(
					/* translators: %s: HTML id, such as "content". */
					_x(
						'Counts the page view when a visitor views the %s element on a tested page.',
						'text',
						'nelio-ab-testing'
					),
					`<code>${ trigger.attributes.value }</code>`
				)
			);

		case 'class':
			return formatHtml(
				sprintf(
					/* translators: %s: HTML id, such as "content". */
					_x(
						'Counts the page view when a visitor views an element with class %s on a tested page.',
						'text',
						'nelio-ab-testing'
					),
					`<code>${ trigger.attributes.value }</code>`
				)
			);
	}
}

function formatHtml( text: string ): JSX.Element {
	return createInterpolateElement( text, { code: <code /> } );
}

// =====
// HOOKS
// =====

const useVisibilityTrigger = () => {
	const triggers = useExperimentAttribute( 'pageViewTriggers', [] );
	return triggers.find(
		( t ): t is ConversionAction< ElementViewAttributes > =>
			t.type === 'nab/element-view'
	);
};
