/**
 * WordPress dependencies
 */
import {
	Dashicon,
	SelectControl,
	ToggleGroupControl,
	ToggleGroupControlOption,
} from '@safe-wordpress/components';
import { useSelect } from '@safe-wordpress/data';
import { createInterpolateElement, useState } from '@safe-wordpress/element';
import { _x, sprintf } from '@safe-wordpress/i18n';

/**
 * External dependencies
 */
import {
	store as NAB_DATA,
	usePageAttribute,
	usePluginSetting,
} from '@nab/data';
import { EMPTY_OBJECT } from '@nab/utils';
import type {
	AlternativeTrackingData,
	ECommercePlugin,
	GoalId,
	GoalWinner,
	Maybe,
} from '@nab/types';

/**
 * Internal dependencies
 */
import './style.scss';

import { ArpcChart } from './arpc-chart';
import { ArpcImprovementChart } from './arpc-improvement-chart';
import { ArpcTimelineChart } from './arpc-timeline-chart';
import { ConversionRatesChart } from './conversion-rates-chart';
import { ConversionRatesTimelineChart } from './conversion-rates-timeline-chart';
import { ViewsAndConversionsTimelineChart } from './views-and-conversions-timeline-chart';
import { ConversionImprovementChart } from './conversion-improvement-chart';
import { RevenueChart } from './revenue-chart';
import { RevenueImprovementChart } from './revenue-improvement-chart';
import { RevenueTimelineChart } from './revenue-timeline-chart';
import { useAreUniqueResultsVisible } from '../hooks';

type ChartType =
	'conversion-rate' | 'views-and-conversions' | 'revenue' | 'arpc';

export const EvolutionSection = (): JSX.Element => {
	const status = useExperimentStatus();
	const [ activeTimeline, setActiveTimeline ] =
		useState< ChartType >( 'conversion-rate' );

	return (
		<div className="nab-evolution-section">
			<div className="nab-evolution-section__first-fold">
				<Title />
				<p>
					{ sprintf(
						'%1$s %2$s',
						'running' === status
							? _x(
									'Compare every variant and explore how the test is evolving over time.',
									'user',
									'nelio-ab-testing'
								)
							: _x(
									'Compare every variant and explore how the test evolved over time.',
									'user',
									'nelio-ab-testing'
								),
						_x(
							'These charts help you better understand the results.',
							'text',
							'nelio-ab-testing'
						)
					) }
				</p>
				<ChartSelector
					value={ activeTimeline }
					onChange={ setActiveTimeline }
				/>
				<TimelineChart type={ activeTimeline } />
			</div>
			<ExtraCharts type={ activeTimeline } />
		</div>
	);
};

// ============
// HELPER VIEWS
// ============

const Title = () => (
	<h2>
		{ createInterpolateElement(
			sprintf(
				/* translators: %s: Dashicon. */
				_x( '%s Performance Analysis', 'text', 'nelio-ab-testing' ),
				'<icon />'
			),
			{
				icon: (
					<Dashicon
						className="nab-evolution-section__title-icon"
						icon="chart-bar"
					/>
				),
			}
		) }
	</h2>
);

const ChartSelector = ( {
	value,
	onChange,
}: {
	value: ChartType;
	onChange: ( v: ChartType ) => void;
} ) => {
	const [ timeGrouping, setTimeGrouping ] = usePageAttribute(
		'results/timeGrouping',
		'daily'
	);
	const { ecommerce } = useAttributes();
	const isLoading = useIsLoadingResults();

	return (
		<div className="nab-evolution-section__timeline-selector">
			<ToggleGroupControl
				label=""
				value={ value }
				onChange={ ( newValue ) => onChange( newValue as ChartType ) }
			>
				<ToggleGroupControlOption
					value="conversion-rate"
					label={ _x(
						'Conversion Rates',
						'text',
						'nelio-ab-testing'
					) }
				/>

				<ToggleGroupControlOption
					value="views-and-conversions"
					label={ _x(
						'Views and Conversions',
						'text',
						'nelio-ab-testing'
					) }
				/>

				{ !! ecommerce && (
					<>
						<ToggleGroupControlOption
							value="revenue"
							label={ _x(
								'Revenue',
								'text',
								'nelio-ab-testing'
							) }
						/>

						<ToggleGroupControlOption
							value="arpc"
							label={ _x( 'ARPC', 'text', 'nelio-ab-testing' ) }
							showTooltip={ true }
						/>
					</>
				) }
			</ToggleGroupControl>
			<SelectControl
				options={ [
					{
						value: 'daily' as const,
						label: _x( 'Daily', 'text', 'nelio-ab-testing' ),
					},
					{
						value: 'weekly' as const,
						label: _x( 'Weekly', 'text', 'nelio-ab-testing' ),
					},
					{
						value: 'monthly' as const,
						label: _x( 'Monthly', 'text', 'nelio-ab-testing' ),
					},
				] }
				value={ timeGrouping }
				onChange={ setTimeGrouping }
				disabled={ isLoading }
			/>
		</div>
	);
};

type ChartFunction = ( props: { type: ChartType } ) => JSX.Element | null;
const TimelineChart: ChartFunction = ( { type } ) => {
	const [ timeGrouping ] = usePageAttribute(
		'results/timeGrouping',
		'daily'
	);
	const { activeGoal, alternatives, areResultsUnique, ecommerce, winners } =
		useAttributes();

	const firstDayOfWeek = usePluginSetting( 'firstDayOfWeek' );

	const winner = winners[ activeGoal ]?.alternative;

	switch ( type ) {
		case 'conversion-rate':
			return (
				<div className="nab-evolution-section__timeline-graphic">
					<ConversionRatesTimelineChart
						alternatives={ alternatives }
						firstDayOfWeek={ firstDayOfWeek }
						goal={ activeGoal }
						unique={ areResultsUnique }
						winner={ winner }
						timeGrouping={ timeGrouping }
					/>
				</div>
			);

		case 'views-and-conversions':
			return (
				<div className="nab-evolution-section__timeline-graphic">
					<ViewsAndConversionsTimelineChart
						alternatives={ alternatives }
						firstDayOfWeek={ firstDayOfWeek }
						goal={ activeGoal }
						unique={ areResultsUnique }
						winner={ winner }
						timeGrouping={ timeGrouping }
					/>
				</div>
			);

		case 'revenue':
			if ( ! ecommerce ) {
				return null;
			}
			return (
				<div className="nab-evolution-section__timeline-graphic">
					<RevenueTimelineChart
						alternatives={ alternatives }
						firstDayOfWeek={ firstDayOfWeek }
						goal={ activeGoal }
						unique={ areResultsUnique }
						winner={ winner }
						timeGrouping={ timeGrouping }
					/>
				</div>
			);

		case 'arpc':
			if ( ! ecommerce ) {
				return null;
			}
			return (
				<div className="nab-evolution-section__timeline-graphic">
					<ArpcTimelineChart
						alternatives={ alternatives }
						firstDayOfWeek={ firstDayOfWeek }
						goal={ activeGoal }
						unique={ areResultsUnique }
						winner={ winner }
						timeGrouping={ timeGrouping }
					/>
				</div>
			);
	}
};

const ExtraCharts: ChartFunction = ( { type } ) => (
	<div className="nab-evolution-section__comparison-and-improvement-graphics">
		<div className="nab-evolution-section__comparison-graphic">
			<ComparisonChart type={ type } />
		</div>
		<div className="nab-evolution-section__improvement-graphic">
			<ImprovementChart type={ type } />
		</div>
	</div>
);

const ComparisonChart: ChartFunction = ( { type } ) => {
	const {
		activeGoal,
		alternatives,
		areResultsUnique,
		ecommerce,
		minConfidence,
		winners,
	} = useAttributes();

	switch ( type ) {
		case 'conversion-rate':
		case 'views-and-conversions':
			return (
				<ConversionRatesChart
					alternatives={ alternatives }
					goal={ activeGoal }
					winners={ winners }
					minConfidence={ minConfidence }
					unique={ areResultsUnique }
				/>
			);

		case 'revenue':
			if ( ! ecommerce ) {
				return null;
			}
			return (
				<RevenueChart
					alternatives={ alternatives }
					goal={ activeGoal }
					unique={ areResultsUnique }
				/>
			);

		case 'arpc':
			if ( ! ecommerce ) {
				return null;
			}
			return (
				<ArpcChart
					alternatives={ alternatives }
					goal={ activeGoal }
					unique={ areResultsUnique }
				/>
			);
	}
};

const ImprovementChart: ChartFunction = ( { type } ) => {
	const { activeGoal, alternatives, areResultsUnique, ecommerce } =
		useAttributes();

	switch ( type ) {
		case 'conversion-rate':
		case 'views-and-conversions':
			return (
				<ConversionImprovementChart
					alternatives={ alternatives }
					goal={ activeGoal }
					unique={ areResultsUnique }
				/>
			);

		case 'revenue':
			if ( ! ecommerce ) {
				return null;
			}
			return (
				<RevenueImprovementChart
					alternatives={ alternatives }
					goal={ activeGoal }
					unique={ areResultsUnique }
				/>
			);

		case 'arpc':
			if ( ! ecommerce ) {
				return null;
			}
			return (
				<ArpcImprovementChart
					alternatives={ alternatives }
					goal={ activeGoal }
					unique={ areResultsUnique }
				/>
			);
	}
};

// =====
// HOOKS
// =====

const useExperimentStatus = () =>
	useSelect( ( select ): 'running' | 'finished' => {
		const activeExperiment =
			select( NAB_DATA ).getPageAttribute( 'editor/activeExperiment' ) ??
			0;
		const status = select( NAB_DATA ).getExperimentAttribute(
			activeExperiment,
			'status'
		);
		return 'finished' === status ? 'finished' : 'running';
	}, [] );

const useAttributes = () => {
	const [ areResultsUnique ] = useAreUniqueResultsVisible();
	return useSelect(
		(
			select
		): {
			readonly activeGoal: GoalId;
			readonly areResultsUnique: boolean;
			readonly ecommerce: Maybe< ECommercePlugin >;
			readonly alternatives: Maybe<
				ReadonlyArray< AlternativeTrackingData >
			>;
			readonly winners: Partial< Record< GoalId, GoalWinner > >;
			readonly minConfidence: number;
		} => {
			const {
				getAlternativeResultsInExperiment,
				getExperimentAttribute,
				getPageAttribute,
				getPluginSetting,
				getWinnersInExperiment,
				getECommercePlugin,
			} = select( NAB_DATA );

			const activeExperiment =
				getPageAttribute( 'editor/activeExperiment' ) ?? 0;
			const goals =
				getExperimentAttribute( activeExperiment, 'goals' ) ?? [];
			const activeGoalId =
				getPageAttribute( 'editor/activeGoal' ) ?? goals[ 0 ]?.id ?? '';

			return {
				activeGoal: activeGoalId,
				areResultsUnique,
				ecommerce: getECommercePlugin( activeExperiment, activeGoalId ),
				alternatives:
					getAlternativeResultsInExperiment( activeExperiment ),
				winners:
					getWinnersInExperiment( activeExperiment ) ?? EMPTY_OBJECT,
				minConfidence: getPluginSetting( 'minConfidence' ),
			};
		},
		[ areResultsUnique ]
	);
};

const useIsLoadingResults = () => {
	const [ activeExperiment ] = usePageAttribute(
		'editor/activeExperiment',
		0
	);
	return useSelect(
		( select ) =>
			! select( NAB_DATA ).hasFinishedResolution(
				'getExperimentResults',
				[ activeExperiment ]
			),
		[ activeExperiment ]
	);
};
