export const HelpButton = (): JSX.Element | null => {
	const [ isPublicView ] = usePageAttribute( 'results/isPublicView', false );
	if ( isPublicView ) {
		return null;
	}
	return (
		<ContextualHelpButton
			placement="bottom-start"
			screen="results"
			questions={ questions }
			walkthrough={ walkthrough }
		/>
	);
};

