/**
 * WordPress dependencies
 */
import { _x, sprintf } from '@safe-wordpress/i18n';

/**
 * External dependencies
 */
import { last, sum } from 'lodash';
import { Line } from 'react-chartjs-2';
import ChartDataLabels from 'chartjs-plugin-datalabels';
import 'chartjs-adapter-moment';
import {
	Chart as ChartJS,
	BarElement,
	CategoryScale,
	Legend,
	LineElement,
	LinearScale,
	PointElement,
	TimeScale,
	Title,
	Tooltip,
} from 'chart.js';
import { formatNumber } from '@nab/i18n';
import {
	COLORS,
	aggregateResultsByTimeGrouping,
	getLetter,
	getNiceRange,
	makeSlidingWindow,
} from '@nab/utils';

ChartJS.register(
	BarElement,
	CategoryScale,
	ChartDataLabels,
	Legend,
	LineElement,
	LinearScale,
	PointElement,
	TimeScale,
	Title,
	Tooltip
);

import type { ChartDataset, ScatterDataPoint } from 'chart.js';
import type {
	AlternativeTrackingData,
	DayResults,
	GoalId,
	Maybe,
} from '@nab/types';

/**
 * Internal dependencies
 */
import { getEvolutionChartOptions } from './helpers';

export type ConversionRatesTimelineProps = {
	readonly alternatives: Maybe< ReadonlyArray< AlternativeTrackingData > >;
	readonly firstDayOfWeek: number;
	readonly goal: GoalId;
	readonly unique: boolean;
	readonly timeGrouping: 'daily' | 'weekly' | 'monthly';
	readonly winner: Maybe< number >;
};

export const ConversionRatesTimelineChart = ( {
	alternatives = [],
	firstDayOfWeek,
	goal,
	unique,
	winner,
	timeGrouping,
}: ConversionRatesTimelineProps ): JSX.Element => {
	const colors = [
		COLORS.nabBackgroundAlternativeA,
		COLORS.nabBackgroundAlternativeB,
		COLORS.nabBackgroundAlternativeC,
		COLORS.nabBackgroundAlternativeD,
		COLORS.nabBackgroundAlternativeE,
		COLORS.nabBackgroundAlternativeF,
	];

	const pointStyles = [
		{ type: 'circle' as const, size: 2.5 },
		{ type: 'rect' as const, size: 3 },
		{ type: 'triangle' as const, size: 3.5 },
	];

	const lines = alternatives.map( ( a ) =>
		getData( a, goal, unique, timeGrouping, firstDayOfWeek )
	);
	const datasets: ChartDataset[] = lines.map( ( l, i ) => ( {
		label:
			i === 0
				? _x( 'Variant A (Control)', 'text', 'nelio-ab-testing' )
				: sprintf(
						/* translators: %s: Variant letter. */
						_x( 'Variant %s', 'text', 'nelio-ab-testing' ),
						getLetter( i )
					),
		backgroundColor: colors[ i % colors.length ],
		borderColor: colors[ i % colors.length ],
		fill: false,
		tension: 0.4,
		borderWidth: i === winner ? 3 : 2,
		pointStyle: pointStyles[ i % pointStyles.length ]?.type,
		pointRadius:
			( pointStyles[ i % pointStyles.length ]?.size ?? 3 ) *
			( i === winner ? 1.2 : 1 ),
		pointHitRadius: 4,
		pointHoverRadius: 4,
		data: l,
	} ) );

	const options = getEvolutionChartOptions( {
		...computeYAxisInterval( lines ),
		timeGrouping,
		title: _x( 'Conversion Rates', 'text', 'nelio-ab-testing' ),
		yTickTemplate: '%s%%',
		tooltip: ( context ) =>
			sprintf(
				'%1$s: %2$s%%',
				context.dataset.label,
				formatNumber( context.raw.y || 0 )
			),
	} );

	// eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment
	return <Line data={ { datasets } as any } options={ options as any } />;
};

// =======
// HELPERS
// =======

const getData = (
	alternative: Maybe< AlternativeTrackingData >,
	goal: GoalId,
	unique: boolean,
	timeGrouping: 'daily' | 'weekly' | 'monthly',
	firstDayOfWeek: number
): ScatterDataPoint[] => {
	if ( ! alternative ) {
		return [];
	}

	const timeline = makeSlidingWindow(
		aggregateResultsByTimeGrouping(
			alternative.timeline,
			timeGrouping,
			firstDayOfWeek
		),
		alternative.timeline.length
	);
	return timeline.map( ( days ) => {
		const day = last( days ) as DayResults;
		const visits =
			sum(
				days.map( ( d ) =>
					unique ? d.uniqueVisits || 0 : d.visits || 0
				)
			) || 1;
		const conversions = sum(
			days.map( ( d ) =>
				unique
					? d.uniqueConversions[ goal ] || 0
					: d.conversions[ goal ] || 0
			)
		);
		return {
			x: day.date,
			y: Math.round( ( 10_000 * conversions ) / visits ) / 100 || 0,
		} as unknown as ScatterDataPoint;
	} );
};

function computeYAxisInterval(
	lines: ReadonlyArray< ReadonlyArray< ScatterDataPoint > >
): {
	readonly min: number;
	readonly max: number;
} {
	const values: number[] = lines
		.map( ( l ) => removeFirstDays( l ) )
		.flatMap( ( line ) => line.map( ( p ) => p.y ?? 0 ) );
	values.sort( ( a, b ) => a - b );

	const min = values[ 0 ] ?? 0;
	const max = values[ values.length - 1 ] ?? 0;
	const range = max - min;
	const margin = range * 0.15;
	return getNiceRange(
		Math.floor( Math.max( 0, min - margin ) ),
		Math.ceil( max + margin )
	);
}

const removeFirstDays = (
	l: ReadonlyArray< ScatterDataPoint >
): ReadonlyArray< ScatterDataPoint > =>
	l.length < 10 ? l : l.slice( Math.ceil( l.length * 0.1 ), l.length - 1 );
