/**
 * WordPress dependencies
 */
import { dateI18n } from '@safe-wordpress/date';
import { _x, sprintf } from '@safe-wordpress/i18n';

/**
 * External dependencies
 */
import { range } from 'lodash';
import { formatI18nDate } from '@nab/date';
import { getLetter, isNumber } from '@nab/utils';
import type { ChartOptions } from 'chart.js';

type TooltipContext< R > = {
	readonly raw: R;
	readonly dataset: {
		readonly label: string;
	};
};

export function isTooltipContext< R >( x: unknown ): x is TooltipContext< R > {
	return !! x;
}

export function getEvolutionChartOptions( {
	max,
	min,
	ticksPrecision,
	timeGrouping,
	title,
	yTickTemplate = '%s',
	tooltip,
}: {
	readonly max?: number;
	readonly min?: number;
	readonly ticksPrecision?: number;
	readonly timeGrouping: 'daily' | 'weekly' | 'monthly';
	readonly title: string;
	readonly yTickTemplate?: string;
	readonly tooltip: (
		context: TooltipContext< { readonly y: number } >
	) => string;
} ): ChartOptions {
	const xunit = TIME_GROUPING_TO_X_UNIT[ timeGrouping ];
	return {
		layout: {
			padding: {
				left: 0,
				right: 10,
				top: 0,
				bottom: 0,
			},
		},
		responsive: true,
		maintainAspectRatio: false,
		scales: {
			x: {
				type: 'time',
				ticks: {
					autoSkip: true,
					autoSkipPadding: 10,
					maxRotation: 0,
					callback: ( value ) =>
						getTick( new Date( value ).toISOString(), xunit ),
				},
				time: {
					unit: xunit,
				},
			},
			y: {
				afterDataLimits: ( scale ) => {
					scale.min = Math.max( 0, scale.min );
				},
				min,
				max,
				ticks: {
					precision: ticksPrecision,
					callback: ( value: unknown ) =>
						isNumber( value )
							? sprintf( yTickTemplate, value )
							: '',
				},
				title: {
					display: true,
					text: title,
				},
			},
		},
		plugins: {
			tooltip: {
				callbacks: {
					title: ( [ context ] ) =>
						isTooltipContext< { x: string } >( context )
							? getTooltipTitle( context.raw.x, xunit )
							: '',
					label: ( context ) =>
						isTooltipContext< { readonly y: number } >( context )
							? tooltip( context )
							: '',
				},
			},
			legend: {
				labels: {
					usePointStyle: true,
					font: {
						family: '-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Oxygen-Sans,Ubuntu,Cantarell,"Helvetica Neue",sans-serif',
						size: 12,
						style: 'normal',
					},
				},
				position: 'bottom',
			},
			datalabels: { display: false },
		},
	};
}

export const generateNLabels = ( count: number ): ReadonlyArray< string > =>
	range( count ).map( getLetter );

// =======
// HELPERS
// =======

function getTick( day: string, xunit: 'day' | 'week' | 'month' ) {
	switch ( xunit ) {
		case 'day':
		case 'week':
			return dateI18n(
				_x( 'M j', 'text (date in chart tick)', 'nelio-ab-testing' ),
				day
			);

		case 'month':
			const date = new Date( day );
			date.setDate( date.getDate() + 2 );
			return dateI18n( 'M Y', date.toISOString(), 'M Y' );
	}
}

function getTooltipTitle( day: string, xunit: 'day' | 'week' | 'month' ) {
	switch ( xunit ) {
		case 'day':
			return formatI18nDate( day );

		case 'week':
			const start = new Date( day );
			const end = new Date( day );
			end.setDate( end.getDate() + 6 );
			const startString = start.toISOString().substring( 0, 10 );
			const endString = end.toISOString().substring( 0, 10 );
			return sprintf(
				'%1$s – %2$s',
				formatI18nDate( startString ),
				formatI18nDate( endString )
			);

		case 'month':
			const date = new Date( day );
			date.setDate( date.getDate() + 2 );
			return dateI18n( 'M Y', date.toISOString(), 'M Y' );
	}
}

const TIME_GROUPING_TO_X_UNIT: Record<
	'daily' | 'weekly' | 'monthly',
	'day' | 'week' | 'month'
> = {
	daily: 'day',
	weekly: 'week',
	monthly: 'month',
};
