/**
 * WordPress dependencies
 */
import { Dashicon } from '@safe-wordpress/components';
import { useSelect } from '@safe-wordpress/data';
import { _x } from '@safe-wordpress/i18n';

/**
 * External dependencies
 */
import { store as NAB_DATA, useCommercialOpportunity } from '@nab/data';
import type { Maybe } from '@nab/types';

/**
 * Internal dependencies
 */
import './style.scss';
import { useExperimentAttribute } from '../../hooks';
import { SubscribeAction, UpgradeAction } from '@nab/components';
import { createInterpolateElement } from '@wordpress/element';

export const NoQuotaWarning = (): JSX.Element | null => {
	const quota = useSelect(
		( select ) =>
			! select( NAB_DATA ).getPageAttribute( 'results/isPublicView' )
				? select( NAB_DATA ).getQuota()
				: undefined,
		[]
	);
	const status = useExperimentAttribute( 'status' );
	const cta = useCta();

	if ( ! quota || quota.availableQuota ) {
		return null;
	}

	if ( 'running' !== status ) {
		return null;
	}

	return (
		<div className="nab-results-experiment-sidebar__no-quota-warning">
			<Dashicon icon="warning" />
			<span>
				<strong>
					{ _x(
						'Event tracking has stopped because your quota is exhausted.',
						'text',
						'nelio-ab-testing'
					) }
				</strong>{ ' ' }
				{ _x(
					'The test is still active and visitors will continue seeing its variants, but their actions won’t be tracked until it resets.',
					'text',
					'nelio-ab-testing'
				) }
				{ !! cta && <> { cta }</> }
			</span>
		</div>
	);
};

// =====
// HOOKS
// =====

function useCta(): Maybe< JSX.Element > {
	const commercialOpportunity = useCommercialOpportunity();
	switch ( commercialOpportunity.type ) {
		case 'none':
			return undefined;

		case 'boost-expiring':
		case 'low-quota':
		case 'quota-exhausted':
			switch ( commercialOpportunity.action ) {
				case 'subscribe':
					return createInterpolateElement(
						_x(
							'<subscribe>Subscribe for more quota</subscribe> or wait until then.',
							'command',
							'nelio-ab-testing'
						),
						{ subscribe: <SubscribeAction variant="link" /> }
					);

				case 'purchase-quota-or-upgrade':
				case 'upgrade':
					return createInterpolateElement(
						_x(
							'<upgrade>Upgrade for more quota</upgrade> or wait until then.',
							'command',
							'nelio-ab-testing'
						),
						{ upgrade: <UpgradeAction variant="link" /> }
					);
			}
	}
}
